        kb_id      uuid PRIMARY KEY REFERENCES ai_knowledge_bases(id) ON DELETE CASCADE,
        tenant_id  uuid NOT NULL,
        agent_id   uuid NOT NULL,
        embedding  vector(${dim}) NOT NULL,
        created_at timestamptz NOT NULL DEFAULT now()
      );
