SELECT phone_number_id, COUNT(*)::int AS count
      FROM whatsapp_accounts
      WHERE deleted_at IS NULL AND phone_number_id IS NOT NULL
      GROUP BY phone_number_id
      HAVING COUNT(*) > 1;
