DELETE FROM "whatsapp_webhooks" w
      USING "whatsapp_webhooks" dup
      WHERE w."idempotency_key" IS NOT NULL
        AND w."idempotency_key" = dup."idempotency_key"
        AND w."id" > dup."id";
